def reader(path, serial, firmware="4.38.21908"):
    (path / ".kobo").mkdir(parents=True)
    (path / ".kobo/version").write_text(f"{serial},{firmware},hardware-model")
    with sqlite3.connect(path / ".kobo/KoboReader.sqlite") as db:
        db.executescript(
            "CREATE TABLE content (ContentID TEXT, ContentType INTEGER, Title TEXT);"
            "CREATE TABLE Bookmark (BookmarkID TEXT, VolumeID TEXT, Text TEXT);"
            "INSERT INTO content VALUES ('file:///mnt/onboard/book.epub',6,'Book');"
        )
    (path / "book.epub").write_bytes(b"original")
    return path


def identity(mount):
    return native.digest((mount / ".kobo/version").read_bytes())[:20]


def request(root, device):
    if "device" in inspect.signature(kobo.request_removal).parameters:
        return kobo.request_removal(root, "book.epub", device)
    return kobo.request_removal(root, "book.epub")


def worker(root, temporary):
    vault = temporary / "vault"
    vault.mkdir(exist_ok=True)
    result = native.Worker({
        "vault": str(vault), "state": str(temporary / "worker"),
        "highlights_folder": "Highlights", "auto_eject": False,
    })

    def api(route, body=None, binary=False):
        if route == "/v1/device":
            return library.device_state(root, body)
        if route == "/v1/device/inventory":
            library.save_inventory(root, body)
            return {"books": len(body["books"])}
        if route == "/v1/annotations":
            return {"highlights": []}
        if route == "/v1/deliveries":
            return []
        parsed = urlparse(route)
        if parsed.path == "/v1/kobo/commands":
            if "device" in inspect.signature(kobo.pending).parameters:
                return kobo.pending(root, parse_qs(parsed.query).get("device", [""])[0])
            return kobo.pending(root)
        if route.endswith("/claim"):
            return kobo.claim(root, route.split("/")[-2], body["device"])
        if route.endswith("/done"):
            return kobo.complete(root, route.split("/")[-2], **body)
        raise AssertionError(f"Unexpected API call: {route}")

    result.api = api
    return result


def test_same_reader_survives_firmware_update(tmp_path):
    root = tmp_path / "service"
    mount = reader(tmp_path / "reader", "N123456789")
    connector = worker(root, tmp_path)
    connector.synchronize(mount)
    command = request(root, identity(mount))
    (mount / ".kobo/version").write_text("N123456789,4.39.23027,hardware-model")
    connector.synchronize(mount)
    assert not (mount / "book.epub").exists(), (
        "The same reader's removal was stranded by a firmware-only change: "
        + json.dumps(kobo.listing(root))
    )
    assert next(c for c in kobo.listing(root) if c["id"] == command["id"])["state"] == "done"


def test_second_reader_removal_is_not_acknowledged_as_first_readers_order(tmp_path):
