    first = reader(tmp_path / "A", "serial-A")
    second = reader(tmp_path / "B", "serial-B")
    connector = worker(root, tmp_path)
    connector.synchronize(first)
    request(root, identity(first))
    library.save_inventory(root, {"device": identity(second), **native.read_books(second)})
    request(root, identity(second))
    connector.synchronize(second)
    assert not (second / "book.epub").exists(), (
