import subprocess
import sys
from pathlib import Path

import httpx

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'server'))
from margen import app, editor


def test_healthy_legacy_bridge_keeps_ai_available(monkeypatch):
    monkeypatch.setenv('AI_PROVIDER', 'codex-bridge')
    monkeypatch.setenv('CODEX_BRIDGE_URL', 'http://bridge.local')
    monkeypatch.setenv('MARGEN_TOKEN', 'x' * 32)
    base_source = subprocess.check_output(
        ['git', 'show', '6442d72bc18f3af226a0b3e0625ab913e4a91606:server/margen/bridge.py'], text=True
    )
    namespace = {'__package__': 'margen'}
    exec(compile(base_source, '<base bridge>', 'exec'), namespace)
    legacy_health = namespace['health']()
    real_client = httpx.Client

    def transport(request):
        if request.url.path == '/health':
            return httpx.Response(200, json=legacy_health)
        if request.url.path == '/v1/complete':
            return httpx.Response(200, json={'answer': 'synthetic'})
        raise AssertionError(str(request.url))

    monkeypatch.setattr(httpx, 'Client', lambda **kwargs: real_client(
        transport=httpx.MockTransport(transport), **kwargs
    ))
    app.BRIDGE_STATUS.clear()
    assert editor.complete('write', 'synthetic', {}, {}) == {'answer': 'synthetic'}
    baseline_source = subprocess.check_output(
        ['git', 'show', '6442d72bc18f3af226a0b3e0625ab913e4a91606:server/margen/app.py'], text=True
    )
    baseline = {'__package__': 'margen'}
    exec(compile(baseline_source, '<base app>', 'exec'), baseline)
    assert baseline['status']()['ai_available'] is True
    assert app.status()['ai_available'] is True, 'El puente sigue funcionando, pero el servicio nuevo desactiva la IA'

